  "tour.method.lede": "Deine besten Läufe aus zwölf Monaten, Bahnen bewertet nach dem üblichen Niveau der anwesenden Läufer. Gemessen über 15 Saisons: Von zwei Läufern auf derselben Bahn benennt er öfter den, der vorne landet. Und weil er seit 2010 dieselben Regeln und dieselbe Skala behält, zeigt er endlich, ob du dich von Jahr zu Jahr verbesserst.",
