  "footer.rules": "Regeln der Seite und Datenschutz",
  "bridge.moving": "O'CN wird zu Ozimut, unter ozimut.com: Einen Moment, du wirst mit deinen Einstellungen dorthin gebracht.",
  "moved.title": "O'CN wird zu Ozimut",
  "moved.lede": "Die Seite heißt jetzt <b>Ozimut</b> und ist unter <b>ozimut.com</b> zu finden. Dein Konto, deine Einstellungen und deine E-Mail-Alarme bleiben erhalten. Ein paar nützliche Schritte, auf jedem deiner Geräte:",
  "moved.bookmarks": "Aktualisiere deine Lesezeichen: <b>ozimut.com</b>.",
  "moved.push": "Benachrichtigungen müssen auf diesem Gerät erneut erlaubt werden, in den <a href=\"#/reglages\">Einstellungen</a>.",
  "moved.home": "Auf iPhone oder iPad, falls die Seite auf deinem Home-Bildschirm war: Entferne das alte Symbol und füge ozimut.com über Safari hinzu (Teilen › Zum Home-Bildschirm).",
  "moved.ia": "Einen API-Schlüssel, den du für „KI“ gespeichert hattest, musst du erneut eingeben.",
  "moved.method": "Die Methode „Top“ heißt jetzt Ozimut-Methode: Dein CN Top ist jetzt dein Ozimut-Index.",
  "moved.mail": "Die E-Mails der Seite kommen jetzt von alert@ozimut.com; um uns zu schreiben: contact@ozimut.com.",
  "moved.ok": "Verstanden",
  "bridge.waiting.one": "O'CN wird zu Ozimut, unter ozimut.com. Dieser Browser hält noch eine Sendung der Bahnlegung, die auf das Netz wartet: Öffne „Bahnlegung“ online, damit sie gesendet wird, und lade dann die Seite neu, um zu ozimut.com zu wechseln.",
  "bridge.waiting.other": "O'CN wird zu Ozimut, unter ozimut.com. Dieser Browser hält noch {n} Sendungen der Bahnlegung, die auf das Netz warten: Öffne „Bahnlegung“ online, damit sie gesendet werden, und lade dann die Seite neu, um zu ozimut.com zu wechseln.",
  "m.official": "Offizielle CN-Methode",
  "m.fair": "Übliches Niveau",
  "m.top6w": "Ozimut-Methode",
  "m.official.long": "Von der FFCO veröffentlichte Werte",
  "msw.label": "Rangliste",
  "msw.tip": "Zwei Ranglisten aus denselben Ergebnissen: der offizielle CN, veröffentlicht von der FFCO, und der Ozimut-Index, berechnet von dieser Seite.",
  "m.official.tip": "Offiziell: der von der FFCO veröffentlichte CN (Durchschnitt der besten Läufe, jedes Jahr am 1. Januar neu skaliert).",
  "m.top6w.tip": "Ozimut: ein Ozimut-Score pro Lauf (der Ozimut-Bahnwert — der Durchschnitt von üblichem Niveau × Zeit der Schnellsten: 90 % des Feldes im Wald, zwei Drittel im Sprint — geteilt durch die Zeit des Läufers), dann der Ozimut-Index des Läufers, der gewichtete Durchschnitt seiner besten Läufe auf 6 Plätzen. Berechnet aus denselben Ergebnissen wie der offizielle CN.",
  "m.fair.tip": "Das übliche Niveau des Läufers — der gewichtete Durchschnitt seiner besten 60 % Ozimut-Scores, ohne Begrenzung der Plätze —, an dem der Ozimut-Bahnwert gemessen wird.",
  "m.fair.long": "Das übliche Niveau der Läufer, der gewichtete Durchschnitt ihrer besten Läufe, ohne Begrenzung der Plätze; an ihm wird der Ozimut-Bahnwert gemessen",
  "m.top6w.long": "Ein Ozimut-Score pro Lauf, ein Ozimut-Index pro Läufer: der gewichtete Durchschnitt seiner besten Läufe auf 6 Plätzen; die Bahnen gemessen an den Schnellsten des Feldes (90 % im Wald, zwei Drittel im Sprint)",
