  "rn.fed.rank": "{r} von {n}",
  "doc.country.none": "Ozimut hat für dieses Land noch keine Rangliste: Die hier gezeigte Methode und ihre Messungen sind die Frankreichs, wo sie entwickelt wurde.",
  "doc.country.ES": "<b>In Spanien.</b> Die Ozimut-Methode ist dieselbe wie in Frankreich, mit einer Einstellung, die an spanischen Läufen gemessen wurde (Juli 2025 – Oktober 2026, dieselben Läufer): Im Wald wird der Bahnwert aus den schnellsten zwei Dritteln berechnet (statt 90 %), was die Ergebnisse um 0,4 Duellpunkte besser vorhersagt. Spanien hat keinen offiziellen Index als Ausgangspunkt: Die erste Saison des Archivs geht vom üblichen Niveau jeder Kategorie gegenüber H21 aus, wie es in Frankreich gemessen wird, den Rest erledigen die Läufe. Alle Läufer der spanischen Läufe werden klassiert, Ausländer eingeschlossen. Bei denselben Läufern sagt der Ozimut-Index besser voraus, wer vorne landet, als die Regel der FEDO am selben Tag angewendet (Zeit des Kategoriesiegers geteilt durch die des Läufers, Durchschnitt der 6 besten Läufe aus 12 Monaten): +5,0 Duellpunkte im Wald, +5,4 im Sprint. Die Rangliste der FEDO wird so gezeigt, wie sie sie veröffentlicht, im Tab „FEDO-Rangliste“ der Rangliste. Die Studie unten ist die in Frankreich durchgeführte.",
  "rk.tab.fed": "Rangliste {f}",
