  "rl.model": "Das Modell: Auf einer Strecke braucht ein Läufer, bei dem {cnThe} c beträgt, k × Referenzzeit ÷ c; k wird so festgelegt, dass das beste Team aller Vereine (beim CNE der Mittelwert der 5 besten) die Summe der Referenzzeiten ergibt, wie es die FFCO vorsieht. Das beste Team wird exakt berechnet, Zusammensetzungskriterien und reservierte Strecken inbegriffen (Wettkampfordnung 2026). Alter und Geschlecht kommen aus der Kategorie des Läufers: Ein Senior, der H21 läuft, zählt als H21.",
