  "cty.need.title": "Mitgliedern in Frankreich vorbehalten",
  "cty.need.text": "Diese Seite zeigt die Daten des französischen Verbands: Ranglisten, Ergebnisse und Verläufe seiner Lizenzinhaber. Sie öffnet sich den Konten, die Frankreich mit ihrer Lizenznummer beigetreten sind.",
