  "ac.reg.lede.world": "Ozimut steht allen Orientierungsläufern offen: Training, GPS-Analysen, Organisation, Kalender und Laufergebnisse. Die Ranglisten eines Verbands öffnen sich seinen Lizenzinhabern. Die E-Mail-Adresse dient zur Bestätigung deiner Registrierung und zum Zurücksetzen deines Passworts.",
