  "spl.table.hint": "Jede Zelle: die Zeit der Teilstrecke und ihr Rang, die kumulierte Zeit (Rang) und beim Überfahren der Zelle die Abweichung vom üblichen Tempo des Läufers (+: Zeitverlust, −: besser als üblich). Grün: die Bestzeit; rot: ein Fehler ({rule}).",
  "spl.table.hint.ideal": "Ohne Zeitverlust: Der Zeitverlust jedes Fehlers wird abgezogen, die Teilstrecke auf das übliche Tempo des Läufers zurückgeführt; die anderen Teilstrecken bleiben unverändert. Zeiten, kumulierte Zeiten und Ränge werden neu berechnet. Unter Platz und Zeit in Grau die tatsächlichen Werte; beim Überfahren einer Zelle die abgezogene Zeit.",
  "spl.table.hint.touch": "Jede Zelle: die Zeit der Teilstrecke und ihr Rang, die kumulierte Zeit (Rang), dann die Abweichung vom üblichen Tempo des Läufers (+: Zeitverlust, −: besser als üblich). Grün: die Bestzeit; rot: ein Fehler ({rule}).",
  "spl.table.hint.ideal.touch": "Ohne Zeitverlust: Der Zeitverlust jedes Fehlers wird abgezogen, die Teilstrecke auf das übliche Tempo des Läufers zurückgeführt; die anderen Teilstrecken bleiben unverändert. Zeiten, kumulierte Zeiten und Ränge werden neu berechnet. Unter Platz und Zeit in Grau die tatsächlichen Werte; in der letzten Zeile einer Zelle in Rot die abgezogene Zeit.",
