  "os.oc.title": "O-Checklist-Datei für den Start",
  "os.oc.hint": "Die Android-App O Checklist dient am Start dazu, die Starter abzuhaken und Abwesende sowie Chipwechsel zu notieren. Diese Datei lässt sich unverändert importieren.",
