  "os.oc.dl": "O-Checklist-Datei herunterladen",
  "os.oc.note": "Eine CSV-Datei (UTF-8, Kommas): Name, Verein, Klasse, Startnummer, Startzeit, Chip, Start, ein Läufer pro Zeile in Startreihenfolge. Sie bleibt auf deinem Gerät: Nichts wird gesendet.",
  "os.oc.note.nocard": "Eine CSV-Datei (UTF-8, Kommas): Name, Verein, Klasse, Startnummer, Startzeit, Chip, Start, ein Läufer pro Zeile in Startreihenfolge. Diese Datei enthält keine Chipnummern: Ein IOF-XML- oder CSV-Export deiner Software enthält sie. Sie bleibt auf deinem Gerät: Nichts wird gesendet.",
