  "os.privacy": "Dein Konto wird mit dem Upload gespeichert (nur für den Administrator sichtbar). Die Datei wird nach 60 Tagen gelöscht; Namen, Vereine, Kategorien und Startzeiten werden veröffentlicht, nicht Geburtsjahre, Chipnummern oder Startnummern.",
