  "sh.privacy": "Die hier hinzugefügten GPS-Tracks werden an Ozimut gesendet: nur Positionen und Uhrzeiten, beschränkt auf den Kartenbereich (keine Herzfrequenz, keine Kadenz, nichts von der Strecke außerhalb der Karte). Sie sind für alle sichtbar, die die Analyse öffnen können; jeder kann seinen eigenen jederzeit entfernen, und sie verschwinden mit der Analyse oder mit deinem Konto.",
