  "sh.e.drop.hint": "Karte: Bild, PDF oder KMZ · Georeferenzierung: KMZ/KML, World File (+ .prj) · Bahn: IOF XML (Purple Pen, OCAD, Condes) · oder dein eigener GPX/TCX/FIT-Track auf dieser Bahn, mit dem die Karte georeferenziert wird · oder eine OCAD-Bahnlegungsdatei, die alle Bahnen auf einmal liefert",
  "sh.drop": "Leg die Karte und ihre Bahnen hier ab oder klicke, um die Dateien auszuwählen",
