  "sh.ocad.title": "Die Bahnen einer OCAD-Datei importieren",
  "sh.ocad.intro": "Ein OCAD-Bahnlegungsprojekt hält die Bahnen in einer Datei und die Karte meist in einer anderen. Jede angehakte Bahn wird zu einer Bahn der Analyse: ihre Karte mit dem aufgedruckten Bahnverlauf, ihre Posten platziert, ihre Georeferenzierung aus der Karte übernommen. Eine Bahn mit demselben Namen wird ersetzt.",
  "sh.ocad.drop": "Leg die OCAD-Bahnlegungsdatei (.ocd) und ihre Karte hier ab oder klicke, um sie auszuwählen",
