  "sh.ocad.err.noCourses": "{f}: Diese Datei enthält keine Bahn. Nur OCAD-Bahnlegungsdateien enthalten ihre Bahnen; für eine reine Karte leg die Bahnen in „Bahnlegung“ und veröffentliche sie in der Kartenanalyse, oder füge sie einzeln mit einem Bild der Karte hinzu.",
  "sh.ocad.err.noGeo": "{f}: Diese Datei ist nicht georeferenziert, und die Analyse muss wissen, wo die Karte liegt. Georeferenziere sie in OCAD oder füge die Bahnen einzeln mit einer KMZ-Datei oder einem World File hinzu.",
