  "sh.fitTip": "Tipp: Lade möglichst die FIT-Datei deiner Uhr hoch statt einer GPX- oder TCX-Datei: Nur ihre Positionen und Uhrzeiten werden gesendet, aber sie bleibt für „Meine Kurven“ auf diesem Gerät, mit allen Laufdaten (Herzfrequenz, Kadenz, Leistung…), die GPX oder TCX oft verlieren.",
  "an.drop.hint": "die Karte (Bild, PDF, KMZ, OCAD oder Mapper) und den Track (GPX, TCX oder FIT); falls vorhanden, die Georeferenzierungsdatei der Karte (.jgw/.pgw/.wld + .prj, KML) und die Bahndatei (IOF XML aus Purple Pen, OCAD oder Condes)",
