  "up.help.soft": "MeOS, OE12, OE2010, OS, Helga… exportieren sie alle: Wähle den Ergebnisexport im Format „IOF XML 3.0“ (manchmal „IOF 3.0“ oder „XML“ genannt) und behalte die Zwischenzeiten bei.",
  "up.help.else": "Sonst:",
