  "ad.tab.anon": "Anonymisiert",
  "ad.an.lede": "Auf Anfrage (nicht mehr angezeigt werden, gesetzlicher Vertreter eines Minderjährigen, Löschung der Ergebnisdaten) werden Name und Lizenznummer eines Lizenzinhabers auf der gesamten veröffentlichten Website durch „Anonymer Läufer N“ ersetzt. Seine Ergebnisse zählen weiter: Ränge, Bahnwerte, CN und Indizes der anderen Läufer ändern sich nicht. Wird beim nächsten Update der Website angewandt, innerhalb einer Stunde; umkehrbar.",
