  "ad.m.def": "Aktiv: mindestens ein Seitenaufruf in den letzten {n} Tagen (Pariser Zeit). Registriert: ein bestätigtes, nicht deaktiviertes Konto. Ein gelöschtes Konto verschwindet aus dem Verlauf.",
  "ad.st.lede": "Die zu kontaktierenden Veranstalter-Websites: jene, deren robots.txt Robots verbietet (die Sammlung liest sie trotzdem, ein paar Anfragen pro Lauf), und jene, die Robots aktiv blockieren (nie umgangen: Ihre Ergebnisse werden nicht gelesen). Für jede die betroffenen Läufe.",
