  "nav.vma": "MAG",
  "nav.ask": "KI",
  "vma.lede": "Die maximale aerobe Geschwindigkeit (MAG) messen: die Tests, ein genauer Rechner für den halben Cooper- und den Cooper-Test auf der Bahn, deine Trainingstempos und kostenlose Apps für einen Test auf der Bahn.",
  "vma.tab.calc": "Rechner",
  "vma.tab.methods": "Methoden",
  "vma.tab.apps": "Apps",
  "g.lede": "Trainingsspiele zum Kartenlesen, auf Karten, die direkt hier gezeichnet werden: Jede Partie erfindet neue. Nichts wird gesendet; deine besten Scores bleiben in diesem Browser.",
  "g.best": "Bester Score",
  "g.start": "Starten",
  "g.prep": "Karten werden vorbereitet",
  "g.puzzle": "Aufgabe",
