  "g.chooseIn": "Wähle! {n} s",
  "g.go": "Los geht’s",
  "g.done": "Partie beendet:",
  "g.newBest": "neuer Rekord!",
  "g.yourAnswer": "Deine Antwort",
  "g.answer": "Richtige Antwort",
  "g.time": "Zeit",
