  "ia.byok.privacy": "Der Schlüssel bleibt in diesem Browser: Er wird nie an Ozimut gesendet (ohne „Merken“ wird er beim Schließen des Tabs gelöscht; er wird auch beim Abmelden gelöscht). Der Anbieter erhält die Frage, die Beschreibung der Tabellen und deine Lizenznummer — nie die Daten —, gemäß seinen Bedingungen, und berechnet dir seine Preise (eine Frage kostet weniger als einen Cent bis etwa einen Cent). Erstelle einen Schlüssel nur für diesen Zweck, mit einem Ausgabenlimit: Ein Skript auf der Seite könnte ihn lesen.",
