  "rh.ed.hint.cfc": "Der Ort, was die Archive bewahren, die Zahl der Teams jeder Division und die Meister. Divisionen: D1 bis D4 von 2000 bis 2006, N1, N2, Promotion nationale und Promotion von 2007 bis 2009, N1 bis N4 seit 2010.",
  "rh.ed.hint.cne": "Der Ort, was die Archive bewahren, die Zahl der Teams jeder Staffel (Herren · Damen · Jugend · Mini) und die Sieger (der erste gewertete Verein).",
