  "st.arenaM.title": "In Arena verwendete Rangliste",
  "st.arenaM.hint": "Der offizielle CN oder der Ozimut-Index in den Ergebnissen, im Live und in den Läuferfenstern von Arena: der Wert 15 Tage vor dem Lauf, die Scores und der erwartete Rang. In Stats wählst du oben auf den Seiten. Auf diesem Gerät gespeichert.",
