  "cd.s.5.4": "Brücke, Steg",
  "cd.d.5.4": "Ein Übergang über einen Wasserlauf oder ein anderes Linienobjekt.",
  "cd.s.5.5": "Stromleitung",
  "cd.d.5.5": "Eine Strom- oder Telefonleitung, Seilbahn oder ein Skilift.",
  "cd.s.5.6": "Leitungsmast",
  "cd.d.5.6": "Ein Mast einer Strom- oder Telefonleitung, einer Seilbahn oder eines Skilifts.",
  "cd.s.5.7": "Tunnel",
  "cd.d.5.7": "Ein Durchgang unter Straßen, Eisenbahnen usw.",
  "cd.s.5.8": "Mauer",
  "cd.d.5.8": "Eine Mauer aus Stein oder anderen Materialien. Mit Symbol 8.11 für eine verfallene Mauer.",
  "cd.s.5.9": "Zaun",
  "cd.d.5.9": "Eine Begrenzung aus Draht oder Holz. Mit Symbol 8.11 für einen verfallenen Zaun.",
  "cd.s.5.10": "Durchlass",
  "cd.d.5.10": "Ein Durchgang durch oder über eine Mauer, einen Zaun oder ein anderes Linienobjekt, einschließlich Tor oder Zauntritt.",
  "cd.s.5.11": "Gebäude",
  "cd.d.5.11": "Ein von Menschen errichtetes Bauwerk, meist aus Ziegel, Holz oder Stein. Ein Pfeiler, der ein Dach trägt.",
  "cd.s.5.12": "Fahrbahn",
  "cd.d.5.12": "Eine befestigte Fläche, zum Parken oder für andere Zwecke genutzt.",
  "cd.s.5.13": "Ruine",
  "cd.d.5.13": "Die Reste eines verfallenen Gebäudes.",
  "cd.s.5.14": "Markantes künstliches Linienobjekt",
  "cd.d.5.14": "Ein markantes Linienobjekt über dem Boden, wie eine Pipeline (Gas, Wasser, Öl usw.) oder eine Bob- bzw. Skeletonbahn.",
  "cd.s.5.15": "Turm",
  "cd.d.5.15": "Ein Turm, meist aus Metall, Ziegel oder Holz.",
