  "sh.mine.tip": "Du bist der Veranstalter: Verwalte sie im Modul Orga.",
  "cty.need.guest": "Ohne Konto zeigt Stats den Läufer, die Rangliste und die Läufe über den Zeitraum, den der Verband frei veröffentlicht. Erstelle ein Konto und tritt Frankreich bei, um alles zu sehen.",
  "tour.mod.try": "{mod} ohne Konto ausprobieren",
  "tour.mod.orga.cta": "Konto erstellen, um zu organisieren",
  "tour.mod.arena.title": "Der ganze Lauf, davor, währenddessen und danach",
  "tour.mod.arena.lede": "Arena bündelt jeden Wettkampf an einem Ort: den Kalender und seine Anmeldungen, die Startzeiten, sobald sie erscheinen, das Live Posten für Posten, dann die Ergebnisse der Veranstalter, oft noch am selben Abend, mit der vollständigen Analyse der Zwischenzeiten. Wähle einen Lauf, Arena erledigt den Rest.",
  "tour.mod.stats.title": "Die Rangliste, endlich verständlich",
  "tour.mod.stats.lede": "Stats bringt den ganzen OL in Zahlen: dein Index und dein Rang, das genaue Detail jeder Berechnung, deine Fortschritte Saison für Saison auf einem Index, der seit 2010 von Jahr zu Jahr vergleichbar ist, die Vereine, die Staffeln und die Trends des Landes. Vergleiche dich, verfolge deine Rivalen, verstehe jeden gewonnenen oder verlorenen Punkt.",
  "tour.mod.coach.title": "Zwischen zwei Läufen besser werden",
  "tour.mod.coach.lede": "Coach macht aus deinen Tracks Lektionen: Spiel deinen Lauf auf deiner Karte nach, sieh, wo die Sekunden verrinnen, vergleiche deine Routenwahl mit der der anderen. Wiederhole die Postenbeschreibungen, trainiere dein Kartenlesen mit zwölf Spielen und berechne deine MAG.",
  "tour.mod.coach.lede.lim": "Coach macht aus deinen Tracks Lektionen: Spiel deinen Lauf auf deiner Karte nach, sieh, wo die Sekunden verrinnen, vergleiche deine Routenwahl mit der der anderen. Trainiere dein Kartenlesen mit zwölf Spielen und berechne deine MAG.",
  "tour.mod.orga.title": "Veranstalten, ohne sich zu verausgaben",
  "tour.mod.orga.lede": "Orga gibt Vereinen die Werkzeuge für den Wettkampftag und danach: Bahnen im Browser legen, Startzeiten und Ergebnisse veröffentlichen, live aus MeOS übertragen, die Zeiten prüfen und den Läufern ihre Kartenanalyse bieten. Du aktivierst es bei der Registrierung oder in deinen Einstellungen, am Computer.",
  "tour.feat.eyebrow": "Preise",
  "tour.feat.title": "Alles kostenlos, Modul für Modul",
  "tour.feat.lede": "Jede Zeile ergänzt die vorige. Ohne Konto zeigt Ozimut, was öffentlich ist; ein Konto öffnet die Benachrichtigungen und das Teilen von GPS-Tracks, das Modul Orga die Werkzeuge der Veranstalter. Was ein Sternchen trägt, setzt zudem eine Lizenz des Verbands voraus.",
  "tour.feat.note": "Nur für Lizenzinhaber des Verbands: in Frankreich ein Konto, das Frankreich beigetreten ist und dessen FFCO-Lizenznummer anhand des Namens geprüft wurde. Länder, deren Ergebnisse alle öffentlich sind (Spanien), stehen allen offen.",
  "tour.feat.star": "Lizenzinhaber des Verbands",
  "hub.guest.enter": "Ohne Konto weiter",
  "home.guest.or": "oder",
  "home.guest.hint": "Ohne Konto bleiben viele Funktionen registrierten Nutzern vorbehalten: Die meisten erweiterten Funktionen sind nicht sichtbar.",
  "tour.cap.hub.b": "Vier Module,",
  "tour.cap.hub": "zur Wahl beim Ankommen: Das Logo führt jederzeit dorthin zurück.",
  "tour.cap.past.b": "Vergangene Wettkämpfe,",
  "tour.cap.past": "mit allem, was Ozimut zu jedem gefunden hat.",
