  "tour.f.coach.guest.1": "Einzelanalyse: dein GPS-Track (GPX, TCX, FIT) auf deiner Karte (Bild, PDF, KMZ, OCAD, Mapper)",
  "tour.f.coach.guest.2": "Die Bahn von der Karte gelesen, der Track automatisch kalibriert",
