  "tour.f.coach.guest.8": "Die Berechnung der MAG und der Trainingstempi",
  "tour.f.coach.account.1": "Mit den anderen vergleichen: dein Track geteilt auf der Karte des Veranstalters",
  "tour.f.coach.account.2": "Die Wiedergabe mit Massenstart oder ab einem Posten",
  "tour.f.coach.account.3": "Routenvarianten, Abstände und Duell",
  "tour.f.coach.account.4": "Die Übungen der Trainings: Korridore und Kompasskurse",
